#!/usr/bin/env python3
from pathlib import Path
from textwrap import dedent

ROOT = Path(__file__).resolve().parents[2]
OUT = Path.home() / "tmp/public/nilo/agentic-3js-builder/n1/index.html"
OUT.parent.mkdir(parents=True, exist_ok=True)
html = dedent(r'''<!doctype html>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>N1 · Nilo low-poly baseline</title>
<style>
:root{--bg:#0f1115;--card:#171a21;--card2:#12151b;--fg:#e8eaf0;--dim:#8d94a3;--line:#292e39;--n1:#58f287;--craft:#ffb454;--flat:#5ab0ff;--two:#c08cff;--bad:#ff6b6b;--pink:#ff8fb1}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.45 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:28px 32px 72px}h1{font-size:25px;margin:0 0 3px}h2{font-size:18px;margin:34px 0 8px}.sub,.note{color:var(--dim)}.sub{margin-bottom:18px}code{font:12px ui-monospace,monospace;background:#20242d;padding:2px 5px;border-radius:4px}.bad{color:var(--bad)}
.panel{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px 16px}.stats{display:grid;grid-template-columns:repeat(4,minmax(210px,1fr));gap:10px}.stats .n1{border-top:3px solid var(--n1)}.stats .craft{border-top:3px solid var(--craft)}.stats .flat{border-top:3px solid var(--flat)}.stats .two{border-top:3px solid var(--two)}.arm{font-weight:700;font-size:15px}.arm small{color:var(--dim);font-weight:400}.metric{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--line)}.metric:last-child{border:0}.metric b{font-variant-numeric:tabular-nums}.legend{display:flex;gap:16px;flex-wrap:wrap;color:var(--dim);font-size:12px;margin:9px 0}.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}.small{font-size:12px;color:var(--dim)}
.tablewrap{overflow:auto}.compare{border-collapse:collapse;width:100%;min-width:1000px}.compare th,.compare td{border-bottom:1px solid var(--line);padding:8px 9px;text-align:left;vertical-align:top}.compare th{color:var(--dim);font-weight:600}.compare td:first-child{width:150px;font-weight:650}.strip{height:18px;display:flex;gap:2px;min-width:300px}.seg{height:100%;min-width:2px;border-radius:3px;position:relative}.seg span{display:none}.strip:hover .seg span{display:block;position:absolute;z-index:2;top:22px;background:#252b36;color:var(--fg);padding:3px 6px;border-radius:4px;white-space:nowrap;font-size:11px}.design{background:var(--pink)}.build{background:var(--flat)}.run{background:var(--n1)}.crit{background:var(--craft)}
.rowbrief{margin:22px 0 28px}.rowhead{display:flex;align-items:baseline;gap:10px;margin-bottom:7px}.rowhead b{font-size:15px}.rowhead .brief{color:var(--dim);white-space:pre-wrap}.renders{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:8px}.renderGroup{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:7px}.renderGroup h3{font-size:12px;margin:0 0 6px;color:var(--dim)}.thumbs{display:grid;grid-template-columns:repeat(2,1fr);gap:4px}.thumbs img{width:100%;aspect-ratio:1;object-fit:cover;background:#0b0d11;border-radius:4px;display:block}.draft{border:1px dashed var(--pink);margin-bottom:6px;padding:4px;border-radius:5px}.draft label{font-size:10px;color:var(--pink);display:block;margin-bottom:3px}.draft .thumbs{grid-template-columns:repeat(4,1fr)}
@media(max-width:900px){main{padding:20px 14px}.stats{grid-template-columns:repeat(2,minmax(180px,1fr))}.renders{grid-template-columns:1fr}.rowhead{display:block}.brief{display:block;margin-top:3px}}
</style><main><h1>N1 · Nilo low-poly baseline</h1><div class="sub">20 r24 <code>rich</code> briefs · production-shaped loop: design → build → sandbox → critique → build → sandbox · Gemini 3.8 Flash, medium reasoning</div><div id="stats" class="stats"></div><p class="note">Source: controlled run records in <code>results.json</code>; comparison arms are Sonnet 5.5 medium from r35sm. Times are wall-clock seconds, costs use list pricing. A final build has no critic by design.</p><h2>Timing strips</h2><div class="legend"><span><i class="design"></i>design</span><span><i class="build"></i>build</span><span><i class="run"></i>sandbox run</span><span><i class="crit"></i>critique</span></div><div id="timing" class="tablewrap"></div><h2>Same brief, different pipeline</h2><div class="note">Low-poly shows final four views and, where a second valid build existed, the first valid draft. r35 shows the flat and two-stage representative render for the same brief.</div><div id="rows"></div></main><script>
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const med=a=>{a=a.filter(Number.isFinite).sort((x,y)=>x-y);return a.length?a[Math.floor(a.length/2)]:null};
const range=a=>{a=a.filter(Number.isFinite);return a.length?`${Math.min(...a).toFixed(1)}–${Math.max(...a).toFixed(1)}`:'—'};
const fmt=(x,d=1)=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:d});
function n1Totals(rows){window.N1MAX=Math.max(...rows.map(r=>r.wallMs||0));return rows.map(r=>({first:(r.firstValidMs??NaN)/1000,final:(r.wallMs??NaN)/1000,calls:r.callCount??NaN,in:r.calls?.reduce((s,c)=>s+(c.usage?.prompt_tokens??0),0)??NaN,out:r.calls?.reduce((s,c)=>s+(c.usage?.completion_tokens??0),0)??NaN,think:r.calls?.reduce((s,c)=>s+(c.reasoningTokens??0),0)??NaN,cost:r.costUsd??NaN,tris:r.final?.triangles??NaN,fail:r.ok?0:1}));}
const fx=c=>c&&!c.img&&c.fix?{...c,img:c.fix.img,sheet:c.fix.sheet,tris:c.fix.tris}:(c||{});
function r35Arm(data,key){return data.rows.map(r=>{const c=fx(r.cells[key]);const final=c.toWorking??NaN;const first=key==='s:two'&&c.stage2?.stage1Ms?c.stage2.stage1Ms/1000:final;return {first,final,calls:key==='s:two'?8:1,in:NaN,out:c.out??NaN,think:c.think??NaN,cost:c.cost??NaN,tris:c.tris??NaN,fail:c.usable?0:1}})}
function panel(label,cls,vals,sub){let rows=[['First pixel',`${fmt(med(vals.map(x=>x.first)))} s <small>(${range(vals.map(x=>x.first))})</small>`],['Final',`${fmt(med(vals.map(x=>x.final)))} s <small>(${range(vals.map(x=>x.final))})</small>`],['Calls',`${fmt(med(vals.map(x=>x.calls)),0)} <small>(${range(vals.map(x=>x.calls))})</small>`],['Tokens',`${fmt(med(vals.map(x=>x.in)),0)} in · ${fmt(med(vals.map(x=>x.out)),0)} out <small>· ${fmt(med(vals.map(x=>x.think)),0)} reasoning</small>`],['Cost',`$${fmt(med(vals.map(x=>x.cost)),3)} <small>(${range(vals.map(x=>x.cost))})</small>`],['Triangles',`${fmt(med(vals.map(x=>x.tris)),0)} <small>(${range(vals.map(x=>x.tris))})</small>`],['Failures',`${fmt(vals.reduce((s,x)=>s+x.fail,0),0)} / ${vals.length}`]];return `<section class="panel ${cls}"><div class="arm">${label} <small>${esc(sub)}</small></div>${rows.map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join('')}</section>`}
function segment(calls,runs){const seg=[];for(const c of calls){const type=c.role==='design'?'design':c.role==='critique'?'crit':'build';seg.push({type,label:`${c.role}${c.round?` ${c.round}`:''}`,ms:c.latencyMs||0});const run=runs?.[seg.filter(x=>x.type==='build').length-1];if(type==='build'&&run)seg.push({type:'run',label:`sandbox ${run.ok?'ok':'failed'}`,ms:run.wallMs||0});}const sum=seg.reduce((s,x)=>s+x.ms,0);const total=Math.max(window.N1MAX||0,sum)||1;return `<div class="strip">${seg.map(x=>`<div class="seg ${x.type}" style="flex:${x.ms/total}"><span>${esc(x.label)} · ${(x.ms/1000).toFixed(1)}s</span></div>`).join('')}<div style="flex:${(total-sum)/total}"></div></div>`}
function imgs(paths){return (paths||[]).map(p=>`<img loading="lazy" src="${esc(p)}" alt="low-poly view">`).join('')}
(async()=>{const [n1,r35]=await Promise.all([fetch('results.json').then(r=>r.json()),fetch('../r35/data.json').then(r=>r.json())]);const n=n1Totals(n1.subjects), craft=r35Arm(r35,'s:medium'),flat=r35Arm(r35,'s:flat'),two=r35Arm(r35,'s:two',true);$('#stats').innerHTML=panel('N1 low-poly','n1',n,'Gemini 3.8 Flash')+panel('craft3','craft',craft,'Sonnet 5.5 · r35sm')+panel('flat','flat',flat,'Sonnet 5.5 · r35sm')+panel('two-stage','two',two,'Sonnet 5.5 · r35sm');
$('#timing').innerHTML='<table class="compare"><tr><th>Brief</th><th>Low-poly sequence</th><th>Outcome</th></tr>'+n1.subjects.map(r=>`<tr><td>${esc(r.id)}</td><td>${segment(r.calls,r.sandboxRuns)}</td><td class="small">${r.ok?'final '+fmt((r.wallMs||0)/1000)+'s · '+r.callCount+' calls':'failed'}${r.final?.triangles?` · ${fmt(r.final.triangles,0)} tris`:''}</td></tr>`).join('')+'</table>';
$('#rows').innerHTML=n1.subjects.map(r=>{const rr=r35.rows.find(x=>x.id===r.id)||{brief:''},flatc=fx(rr.cells?.['s:flat']),twoc=fx(rr.cells?.['s:two']);return `<article class="rowbrief"><div class="rowhead"><b>${esc(r.id)}</b><span class="brief">${esc(rr.brief)}</span></div><div class="renders"><div class="renderGroup"><h3>N1 low-poly · final ${r.final?`${fmt(r.final.triangles,0)} tris · ${fmt(r.final.glbBytes/1024,1)} KB`:''}</h3>${r.final?.draftDiffers?`<div class="draft"><label>round 1 draft</label><div class="thumbs">${imgs(r.final.draftRenderPaths)}</div></div>`:''}<div class="thumbs">${imgs(r.final?.renderPaths)}</div></div><div class="renderGroup"><h3>r35sm · flat · ${fmt(flatc.tris,0)} tris</h3><div class="thumbs">${flatc.img?`<a href="${esc(flatc.sheet||flatc.img)}" style="grid-column:1/-1"><img src="${esc(flatc.img)}" alt="r35 flat"></a>`:''}</div></div><div class="renderGroup"><h3>r35sm · two-stage · ${fmt(twoc.tris,0)} tris</h3><div class="thumbs">${twoc.img?`<a href="${esc(twoc.sheet||twoc.img)}" style="grid-column:1/-1"><img src="${esc(twoc.img)}" alt="r35 two-stage"></a>`:''}</div></div></div></article>`}).join('');})();
</script>''')
OUT.write_text(html)
print(OUT)
